<?php
if(!defined('ABSPATH'))exit;
add_action('after_setup_theme',function(){add_theme_support('title-tag');add_theme_support('post-thumbnails');});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('coopconnect',get_stylesheet_uri(),array(),'1.0.0');wp_enqueue_script('coopconnect',get_template_directory_uri().'/app.js',array(),'1.0.0',true);});
add_action('wp_head',function(){if(!has_site_icon())echo '<link rel="icon" type="image/svg+xml" href="'.esc_url(get_template_directory_uri().'/favicon.svg').'">';});
function co_content(){return array('co_grant'=>array(array('Enterprise growth fund','An example opportunity to explore expansion, capacity and sustainable enterprise development.','Enterprise','✦'),array('Community innovation grant','An illustrative funding pathway for cooperative-led community innovation.','Innovation','◎'),array('Skills and capability support','Explore an example grant supporting learning and organisational development.','Training','◇')),'co_programme'=>array(array('Cooperative formation','Explore governance, registration preparation and shared enterprise structures.','Development','◎'),array('Business growth & training','Explore capacity building, leadership and sustainable enterprise planning.','Training','◇'),array('Partnership development','Connect the concept of collaborative enterprise with partnerships and networks.','Partnership','✦')),'co_resource'=>array(array('Cooperative governance checklist','Sample checklist covering roles, meetings, decisions and accountability.','Governance','▤'),array('Grant readiness guide','Illustrative guide to preparing documentation and a project plan.','Funding','▤'),array('Enterprise planning framework','Sample framework for a cooperative business plan and milestones.','Planning','▤'),array('Impact reporting template','Example framework for tracking outcomes and reporting progress.','Reporting','▤')));}
add_action('init',function(){foreach(array('co_grant'=>'Grant opportunities','co_programme'=>'Development programmes','co_resource'=>'Resources') as $type=>$label){register_post_type($type,array('label'=>$label,'public'=>true,'has_archive'=>true,'show_in_rest'=>true,'supports'=>array('title','editor','excerpt','thumbnail'),'menu_icon'=>'dashicons-chart-area'));}register_taxonomy('co_topic',array_keys(co_content()),array('label'=>'Topics','public'=>true,'show_in_rest'=>true));});
add_action('after_switch_theme',function(){if(get_option('co_seeded_v1'))return;foreach(co_content() as $type=>$entries){foreach($entries as $entry){$id=wp_insert_post(array('post_type'=>$type,'post_title'=>$entry[0],'post_content'=>$entry[1],'post_status'=>'publish'),true);if(!is_wp_error($id)){wp_set_object_terms($id,$entry[2],'co_topic');update_post_meta($id,'co_icon',$entry[3]);}}}update_option('co_seeded_v1',1);flush_rewrite_rules();});
function co_cards($type){$q=new WP_Query(array('post_type'=>$type,'posts_per_page'=>-1,'orderby'=>'date','order'=>'ASC'));while($q->have_posts()){$q->the_post();$terms=wp_get_post_terms(get_the_ID(),'co_topic',array('fields'=>'names'));$topic=is_wp_error($terms)?'':implode(' · ',$terms);$body=wp_strip_all_tags(get_the_content());?><article class="card searchable" data-search="<?php echo esc_attr(get_the_title().' '.$topic.' '.$body); ?>"><span class="card-icon" aria-hidden="true"><?php echo esc_html(get_post_meta(get_the_ID(),'co_icon',true)?:'▤'); ?></span><span class="tag"><?php echo esc_html($topic); ?></span><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html($body); ?></p><a class="more" href="<?php the_permalink(); ?>">View details</a></article><?php }wp_reset_postdata();}
